    async def record_agent_decision(
        self,
        session_id: str,
        *,
        idempotency_key: str,
        interpretation: str,
        next_action: AgentDecisionNextAction,
        assessment: typing.Optional[AgentDecisionAssessment] = OMIT,
        next_detail: typing.Optional[str] = OMIT,
        evidence_action_ids: typing.Optional[typing.Sequence[str]] = OMIT,
        evaluation_ids: typing.Optional[typing.Sequence[str]] = OMIT,
        next_action_id: typing.Optional[str] = OMIT,
        intervention_id: typing.Optional[str] = OMIT,
        supersedes_decision_id: typing.Optional[str] = OMIT,
        model: typing.Optional[AgentModelIdentity] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> AgentDecisionResponse:
        """
        Append the agent's reading of a result and its next step to the session's audit.

        Only the session's creator records decisions. Recording changes no session state, so it
        is allowed in every session status; it never dispatches, commits, or applies anything.

        Parameters
        ----------
        session_id : str

        idempotency_key : str

        interpretation : str
            Concise reasoning the agent states for the decision, citing the evidence

        next_action : AgentDecisionNextAction

        assessment : typing.Optional[AgentDecisionAssessment]
            How the agent judged the evidence; omitted when not stated

        next_detail : typing.Optional[str]
            The chosen next step

        evidence_action_ids : typing.Optional[typing.Sequence[str]]
            Actions of this session whose results the decision reads

        evaluation_ids : typing.Optional[typing.Sequence[str]]
            Evaluations of those actions' task results

        next_action_id : typing.Optional[str]
            The action of this session that carries out the next step, when one exists

        intervention_id : typing.Optional[str]
            The intervention of this session the decision opened or acts on

        supersedes_decision_id : typing.Optional[str]
            An earlier decision of this session that this record corrects

        model : typing.Optional[AgentModelIdentity]
            The provider and model the client host reports it ran the agent with, read from the host's own runtime, never from the agent's tool arguments. Recorded as reported; QDash does not verify it, and it changes no scope or approval. Omitted when the host does not know it.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        AgentDecisionResponse
            Successful Response

        Examples
        --------
        import asyncio

        from qdash.sdk._generated import AsyncQDashApi

        client = AsyncQDashApi(
            project_id="YOUR_PROJECT_ID",
            token="YOUR_TOKEN",
            base_url="https://yourhost.com/path/to/api",
        )


        async def main() -> None:
            await client.agent_session.record_agent_decision(
                session_id="session_id",
                idempotency_key="idempotency_key",
                interpretation="interpretation",
                next_action="next_task",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.record_agent_decision(
            session_id,
            idempotency_key=idempotency_key,
            interpretation=interpretation,
            next_action=next_action,
            assessment=assessment,
            next_detail=next_detail,
            evidence_action_ids=evidence_action_ids,
            evaluation_ids=evaluation_ids,
            next_action_id=next_action_id,
            intervention_id=intervention_id,
            supersedes_decision_id=supersedes_decision_id,
            model=model,
            request_options=request_options,
        )
        return _response.data

